export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;

interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEMS: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};

export function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + MAIN_ITEMS[item.type].basePremium, 0);
}

export function quotePremium(
  items: Item[],
  _customer: Customer,
  _previousContracts: number,
): number {
  return policyBasePremium(items) + PROCESSING_FEE;
}
EOF
